-- Official U.S. adult component portions, checked 2026-09-27.
-- Source date is intentionally NULL: filename and footer provide differing months.
-- Taco tortilla fiber is <1 g in source; retained as unknown, never fabricated.
-- Chips values are for the whole 4 oz order, not one half of that order.
begin;
on conflict(source,source_id) where source_id is not null do update set
  name=excluded.name,
  brand=excluded.brand,
  source_url=excluded.source_url,
  source_release=excluded.source_release,
  source_data_type=excluded.source_data_type,
  serving_grams=excluded.serving_grams,
  serving_amount=excluded.serving_amount,
  serving_unit=excluded.serving_unit,
  portions=excluded.portions,
  nutrient_values=excluded.nutrient_values,
  calories=excluded.calories,
  protein_g=excluded.protein_g,
  carbs_g=excluded.carbs_g,
  fat_g=excluded.fat_g,
  fiber_g=excluded.fiber_g,
  sugar_g=excluded.sugar_g,
  saturated_fat_g=excluded.saturated_fat_g,
  sodium_mg=excluded.sodium_mg;
commit;
